private void LoadNghienCuuKhoaHoc()
{
    ResetSumResearch();
    SIM_TeachingTimeResearch obj = new SIM_TeachingTimeResearch();

    object scienceID = NormalizeFilterValue(uTeacher.ScienceID);
    object subjectGroupID = NormalizeFilterValue(uTeacher.SubjectGroupID);
    object teacherID = NormalizeFilterValue(uTeacher.TeacherID);
    DataTable dtbData = null;

    if (chkFullYear.Checked)
    {
        DataTable dtbSemester1 = SearchTeachingTimeResearch(obj, scienceID, subjectGroupID, teacherID, 1);
        DataTable dtbSemester2 = SearchTeachingTimeResearch(obj, scienceID, subjectGroupID, teacherID, 2);

        bool bolHas1 = dtbSemester1 != null && dtbSemester1.Rows.Count > 0;
        bool bolHas2 = dtbSemester2 != null && dtbSemester2.Rows.Count > 0;

        if (!bolHas1 && !bolHas2)
        {
            BindRepeaterEmpty(rptResearch, ltrEmptyResearch, "Không có dữ liệu nghiên cứu khoa học!");
            return;
        }

        if (bolHas1 && bolHas2)
        {
            dtbData = dtbSemester1.Copy();
            foreach (DataRow drw in dtbSemester2.Rows)
                dtbData.ImportRow(drw);
        }
        else if (bolHas1)
            dtbData = dtbSemester1.Copy();
        else
            dtbData = dtbSemester2.Copy();
    }
    else
    {
        int semester = Convert.ToInt32(uYearSemester.Semester);
        dtbData = SearchTeachingTimeResearch(obj, scienceID, subjectGroupID, teacherID, semester);
    }

    if (dtbData == null || dtbData.Rows.Count == 0)
    {
        BindRepeaterEmpty(rptResearch, ltrEmptyResearch, "Không có dữ liệu nghiên cứu khoa học!");
        return;
    }

    ApplyResearchYearTextColumn(dtbData);
    CalcSumResearch(dtbData);
    BindRepeater(rptResearch, ltrEmptyResearch, dtbData);
}

private DataTable SearchTeachingTimeResearch(SIM_TeachingTimeResearch obj, object scienceID,
    object subjectGroupID, object teacherID, int semester)
{
    return obj.GetDataTable("SIM_TeachingTimeResearch_Search",
        "@ScienceID", scienceID,
        "@SubjectGroupID", subjectGroupID,
        "@TeacherID", teacherID,
        "@YearID", uYearSemester.YearID,
        "@Semester", semester,
        "@Keyword", null);
}

private void ApplyResearchYearTextColumn(DataTable dt)
{
    if (!dt.Columns.Contains("YearText"))
        dt.Columns.Add("YearText", typeof(string));

    string yearText = uYearSemester.YearText;
    if (yearText == null || yearText == "")
    {
        int yearId = Convert.ToInt32(uYearSemester.YearID);
        yearText = String.Format("{0}-{1}", yearId, yearId + 1);
    }

    foreach (DataRow row in dt.Rows)
        row["YearText"] = yearText;
}

