/// <summary>
/// Tổng cộng giờ NCKH được tính:
/// nếu TotalHour >= ResearchHour thì lấy ResearchHour, ngược lại lấy TotalHour.
/// </summary>
private void ApplyResearchTotalHourCounted(DataTable dt)
{
    if (!dt.Columns.Contains("TotalHourCounted"))
        dt.Columns.Add("TotalHourCounted", typeof(decimal));

    foreach (DataRow row in dt.Rows)
    {
        decimal totalHour = ToDecimal(row["TotalHour"]);
        decimal researchHour = ToDecimal(row["ResearchHour"]);

        if (totalHour >= researchHour)
            row["TotalHourCounted"] = researchHour;
        else
            row["TotalHourCounted"] = totalHour;
    }
}

